import { setTimeout as sleep } from "node:timers/promises";
import { isRecord } from "../../internal/is-record.js";
import { trimServiceUrl } from "./activity.js";
export const BOT_FRAMEWORK_TOKEN_SCOPE = "https://api.botframework.com/.default";
const TOKEN_REFRESH_MARGIN_MS = 5 * 60 * 1000;
const MAX_RETRY_AFTER_MS = 5_000;
export class TeamsConnectorError extends Error {
    constructor(status, message) {
        super(message);
        this.status = status;
        this.name = "TeamsConnectorError";
    }
}
export class TeamsCredentialsUnsetError extends Error {
    constructor() {
        super("Teams credentials are not set");
        this.name = "TeamsCredentialsUnsetError";
    }
}
export function teamsTokenEndpoint(tenantId) {
    return `https://login.microsoftonline.com/${encodeURIComponent(tenantId)}/oauth2/v2.0/token`;
}
export async function mintBotFrameworkToken(credentials, fetchImpl = fetch) {
    const response = await fetchImpl(teamsTokenEndpoint(credentials.tenantId), {
        method: "POST",
        headers: { "content-type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
            grant_type: "client_credentials",
            client_id: credentials.appId,
            client_secret: credentials.appPassword,
            scope: BOT_FRAMEWORK_TOKEN_SCOPE,
        }).toString(),
    });
    const payload = await jsonRecord(response);
    const token = payload.access_token;
    if (!response.ok || typeof token !== "string" || token === "") {
        const code = typeof payload.error === "string" ? `: ${payload.error}` : "";
        throw new TeamsConnectorError(response.status, `Bot Framework token request failed with HTTP ${response.status}${code}`);
    }
    const expiresIn = Number(payload.expires_in);
    return { token, expiresInSeconds: Number.isFinite(expiresIn) ? expiresIn : 3600 };
}
export function createTeamsConnector(deps) {
    const fetchImpl = deps.fetch ?? fetch;
    const now = deps.now ?? Date.now;
    let cached;
    const token = async (fresh) => {
        const credentials = await deps.credentials();
        if (credentials === undefined) {
            throw new TeamsCredentialsUnsetError();
        }
        const key = `${credentials.appId}\n${credentials.tenantId}`;
        if (!fresh && cached?.key === key && cached.expiresAtMs - TOKEN_REFRESH_MARGIN_MS > now()) {
            return cached.token;
        }
        const minted = await mintBotFrameworkToken(credentials, fetchImpl);
        cached = { key, token: minted.token, expiresAtMs: now() + minted.expiresInSeconds * 1000 };
        return minted.token;
    };
    const call = async (input) => {
        let fresh = false;
        let waited = false;
        for (;;) {
            const headers = {
                authorization: `Bearer ${await token(fresh)}`,
            };
            if (input.body !== undefined) {
                headers["content-type"] = "application/json";
            }
            const response = await fetchImpl(input.url, {
                method: input.method,
                headers,
                body: input.body === undefined ? undefined : JSON.stringify(input.body),
            });
            if (response.status === 401 && !fresh) {
                fresh = true;
                continue;
            }
            if (response.status === 429 && input.retry429 !== false && !waited) {
                waited = true;
                await sleep(retryAfterMs(response.headers.get("retry-after")));
                continue;
            }
            return response;
        }
    };
    const ok = async (input) => {
        const response = await call(input);
        if (!response.ok) {
            throw new TeamsConnectorError(response.status, `Bot Connector ${input.method} answered HTTP ${response.status}`);
        }
        return response;
    };
    return {
        async send(address, activity) {
            const payload = await jsonRecord(await ok({ method: "POST", url: activitiesUrl(address), body: activity }));
            return { id: typeof payload.id === "string" ? payload.id : "" };
        },
        async update(address, activityId, activity) {
            await ok({
                method: "PUT",
                url: `${activitiesUrl(address)}/${encodeURIComponent(activityId)}`,
                body: { ...activity, id: activityId },
            });
        },
        async delete(address, activityId) {
            await ok({
                method: "DELETE",
                url: `${activitiesUrl(address)}/${encodeURIComponent(activityId)}`,
            });
        },
        async addReaction(address, activityId, reactionType) {
            const response = await call({
                method: "PUT",
                url: `${activitiesUrl(address)}/${encodeURIComponent(activityId)}/reactions/${encodeURIComponent(reactionType)}`,
                retry429: false,
            });
            if (response.status === 409) {
                return;
            }
            if (!response.ok) {
                throw new TeamsConnectorError(response.status, `Bot Connector PUT reaction answered HTTP ${response.status}`);
            }
        },
        async member(input) {
            const response = await call({
                method: "GET",
                url: `${conversationUrl(input)}/members/${encodeURIComponent(input.memberId)}`,
            });
            if (response.status === 404) {
                return undefined;
            }
            if (!response.ok) {
                throw new TeamsConnectorError(response.status, `Bot Connector GET member answered HTTP ${response.status}`);
            }
            const payload = await jsonRecord(response);
            return {
                userRole: typeof payload.userRole === "string" ? payload.userRole : undefined,
                tenantId: typeof payload.tenantId === "string" ? payload.tenantId : undefined,
            };
        },
    };
}
async function jsonRecord(response) {
    const payload = await response.json().catch(() => undefined);
    return isRecord(payload) ? payload : {};
}
function conversationUrl(input) {
    return `${trimServiceUrl(input.serviceUrl)}/v3/conversations/${encodeURIComponent(input.conversationId)}`;
}
function activitiesUrl(address) {
    return `${conversationUrl(address)}/activities`;
}
function retryAfterMs(header) {
    const seconds = header === null ? Number.NaN : Number(header);
    return Number.isFinite(seconds) && seconds >= 0
        ? Math.min(seconds * 1000, MAX_RETRY_AFTER_MS)
        : 1000;
}
